+  return JSON.parse(read(path));
+}
+
+describe('Claude Code plugin marketplace', () => {
+  for (const [name, path] of Object.entries(FILES)) {
+    it(`${name} file exists, is valid JSON and ends with a newline`, () => {
+      expect(existsSync(path)).toBe(true);
